const allowedFields = ['validation_mode', 'persistence_mode', 'validation_run_id', 'source_run_id', 'layer1_results', 'layer2_result'];
for (const key of Object.keys(workflowInput)) {
  if (!allowedFields.includes(key)) throw new Error(`Transient Dashboard contract does not allow field '${key}'.`);
}
const validationRunId = String(workflowInput.validation_run_id || '').trim();
const sourceRunId = String(workflowInput.source_run_id || validationRunId).trim();
const layer1Results = workflowInput.layer1_results || {};
const layer2Result = workflowInput.layer2_result || {};
const expectedAssets = ['USD', 'EUR', 'GOLD', 'NQ', 'BTC'];
const pairOrder = ['EUR/USD', 'XAU/USD', 'BTC/USD', 'NQ/USD'];
if (workflowInput.validation_mode !== true) throw new Error('Transient Dashboard contract requires validation_mode=true.');
if (String(workflowInput.persistence_mode || '').trim() !== 'transient_fixture') throw new Error('Transient Dashboard contract requires persistence_mode=transient_fixture.');
if (!validationRunId || sourceRunId !== validationRunId) throw new Error('Transient Dashboard contract requires matching validation_run_id and source_run_id.');
const uniqueAssets = new Set(Object.keys(layer1Results));
if (uniqueAssets.size !== expectedAssets.length) throw new Error('Transient Dashboard contract requires exactly five unique Layer 1 assets.');
for (const asset of uniqueAssets) {
  if (!expectedAssets.includes(asset)) throw new Error(`Transient Dashboard received unexpected asset ${asset}.`);
}
const orderedAgents = [];
for (const asset of expectedAssets) {
  const result = layer1Results[asset];
  if (!result || typeof result !== 'object') throw new Error(`Transient Dashboard contract is missing layer1_results.${asset}.`);
  if (!result.dashboard_agent || typeof result.dashboard_agent !== 'object') throw new Error(`Transient Dashboard contract is missing layer1_results.${asset}.dashboard_agent.`);
  if (String(result.source_run_id || '').trim() !== sourceRunId) throw new Error(`Transient Dashboard received mismatched source_run_id for ${asset}.`);
  if (String(result.validation_run_id || '').trim() !== validationRunId) throw new Error(`Transient Dashboard received mismatched validation_run_id for ${asset}.`);
  if (String(result.asset || '').trim() !== asset) throw new Error(`Transient Dashboard received wrong asset identity for ${asset}.`);
  orderedAgents.push(result.dashboard_agent);
}
const layer2Dashboard = layer2Result.dashboard && typeof layer2Result.dashboard === 'object' ? layer2Result.dashboard : null;
if (!layer2Dashboard || !Array.isArray(layer2Dashboard.pairs) || layer2Dashboard.pairs.length === 0) throw new Error('Transient Dashboard contract requires a non-empty layer2_result.dashboard.pairs array.');
const layer2SourceRunId = String(layer2Result.source_run_id || layer2Dashboard.source_run_id || '').trim();
const layer2ValidationRunId = String(layer2Result.validation_run_id || layer2Dashboard.validation_run_id || '').trim();
if (layer2SourceRunId && layer2SourceRunId !== sourceRunId) throw new Error('Transient Dashboard received mismatched Layer 2 source_run_id.');
if (layer2ValidationRunId && layer2ValidationRunId !== validationRunId) throw new Error('Transient Dashboard received mismatched Layer 2 validation_run_id.');
const pairMap = new Map();
for (const pair of layer2Dashboard.pairs) {
  if (!pair || typeof pair !== 'object' || !pair.pair) throw new Error('Transient Dashboard contract requires well-formed Layer 2 pair objects.');
  if (pairMap.has(pair.pair)) throw new Error(`Transient Dashboard received duplicate Layer 2 pair ${pair.pair}.`);
  pairMap.set(pair.pair, pair);
}
const orderedPairs = [];
for (const pairName of pairOrder) {
  if (!pairMap.has(pairName)) throw new Error(`Transient Dashboard contract is missing Layer 2 pair ${pairName}.`);
  orderedPairs.push(pairMap.get(pairName));
}
const generatedAt = new Date().toISOString();
const dashboard = {
  schema_version: 1,
  generated_at: generatedAt,
  source_run_id: sourceRunId,
  validation_run_id: validationRunId,
  consistency_status: 'MATCHED',
  consistency_warnings: [],
  dashboard_meta: {
